// P-code semantics check for the SH-3 / SH-3E / SH-2E modules (after Ghidra-Rare's RXEmuTest).
// Reads test/emu/cases.txt (generated by test/emu/cases.py).  For each case that applies to the
// program's language it writes the code at ram:00001000, sets registers and memory, emulates with
// Ghidra's EmulatorHelper until the PC reaches the end of the main code, and compares registers
// and memory with values worked out by hand from the Hitachi programming manuals.
// R15 starts at 8000h.  Code is given as 16-bit words and stored in the language's byte order;
// memory values are numbers stored/read in the language's byte order.
//
// Case file lines: case <name> langs <sh2e|sh3|sh3e>... / code <hex words> / main <len> /
//   set <reg> <value> | set ram:<hexaddr>[/<n>] <value> / expect <same> / end
// Script args: <cases.txt> <outfile>
//@category Testing

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.PrintStream;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import ghidra.app.emulator.EmulatorHelper;
import ghidra.app.script.GhidraScript;
import ghidra.program.model.address.Address;
import ghidra.program.model.address.AddressSet;

public class SHEmuTest extends GhidraScript {

	private static class Case {
		String name;
		String langs = "";
		byte[] words;
		int mainLen = -1;
		Map<String, Long> set = new LinkedHashMap<>();
		Map<String, Long> expect = new LinkedHashMap<>();
	}

	private boolean bigEndian;

	private List<Case> load(String path) throws Exception {
		List<Case> cases = new ArrayList<>();
		Case c = null;
		try (BufferedReader r = new BufferedReader(new FileReader(path))) {
			String line;
			while ((line = r.readLine()) != null) {
				line = line.trim();
				if (line.isEmpty() || line.startsWith("#")) {
					continue;
				}
				String[] f = line.split("\\s+");
				switch (f[0]) {
					case "case":
						c = new Case();
						c.name = f[1];
						for (int i = 3; i < f.length; i++) {
							c.langs += f[i] + " ";
						}
						break;
					case "code": {
						c.words = new byte[(f.length - 1) * 2];
						for (int i = 1; i < f.length; i++) {
							int w = Integer.parseInt(f[i], 16);
							int hi = (w >> 8) & 0xff, lo = w & 0xff;
							c.words[2 * (i - 1)] = (byte) (bigEndian ? hi : lo);
							c.words[2 * (i - 1) + 1] = (byte) (bigEndian ? lo : hi);
						}
						break;
					}
					case "main":
						c.mainLen = Integer.decode(f[1]);
						break;
					case "set":
						c.set.put(f[1], Long.decode(f[2]));
						break;
					case "expect":
						c.expect.put(f[1], Long.decode(f[2]));
						break;
					case "end":
						cases.add(c);
						break;
					default:
						throw new IllegalArgumentException("bad line: " + line);
				}
			}
		}
		return cases;
	}

	private Address addr(String loc) {
		String[] p = loc.split("[:/]");
		return currentProgram.getAddressFactory().getAddressSpace(p[0]).getAddress(
			Long.parseLong(p[1], 16));
	}

	private int size(String loc) {
		String[] p = loc.split("/");
		return p.length > 1 ? Integer.parseInt(p[1]) : 1;
	}

	private byte[] encode(long value, int n) {
		byte[] b = new byte[n];
		for (int i = 0; i < n; i++) {
			int shift = bigEndian ? 8 * (n - 1 - i) : 8 * i;
			b[i] = (byte) (value >> shift);
		}
		return b;
	}

	private long decode(byte[] b) {
		long v = 0;
		for (int i = 0; i < b.length; i++) {
			v = bigEndian ? (v << 8) | (b[i] & 0xff) : v | ((long) (b[i] & 0xff) << (8 * i));
		}
		return v;
	}

	private String runCase(Case c) throws Exception {
		Address start = addr("ram:1000");
		int mainLen = c.mainLen >= 0 ? c.mainLen : c.words.length;
		Address end = start.add(mainLen);
		AddressSet body = new AddressSet(start, start.add(c.words.length + 16));
		clearListing(body);
		setBytes(start, c.words);
		final EmulatorHelper emu = new EmulatorHelper(currentProgram);
		try {
			emu.writeRegister("R15", 0x8000);
			for (Map.Entry<String, Long> e : c.set.entrySet()) {
				if (e.getKey().contains(":")) {
					emu.writeMemory(addr(e.getKey()), encode(e.getValue(), size(e.getKey())));
				}
				else {
					emu.writeRegister(e.getKey(), e.getValue());
				}
			}
			emu.writeRegister(emu.getPCRegister(), start.getOffset());
			int steps = 0;
			while (!emu.getExecutionAddress().equals(end)) {
				if (++steps > 2000) {
					return "did not reach the end (pc " + emu.getExecutionAddress() + ")";
				}
				if (!emu.step(monitor)) {
					return "emulation error at " + emu.getExecutionAddress() + ": " +
						emu.getLastError();
				}
			}
			StringBuilder bad = new StringBuilder();
			for (Map.Entry<String, Long> e : c.expect.entrySet()) {
				long got;
				long want = e.getValue();
				if (e.getKey().contains(":")) {
					int n = size(e.getKey());
					got = decode(emu.readMemory(addr(e.getKey()), n));
				}
				else {
					got = emu.readRegister(e.getKey()).longValue();
					if (currentProgram.getRegister(e.getKey()).getBitLength() <= 8) {
						got &= 0xff;
					}
					else {
						got &= 0xffffffffL;
					}
				}
				if (got != want) {
					bad.append(String.format(" %s=0x%x (expected 0x%x)", e.getKey(), got, want));
				}
			}
			return bad.length() == 0 ? null : bad.toString().trim();
		}
		finally {
			emu.dispose();
		}
	}

	@Override
	protected void run() throws Exception {
		String[] args = getScriptArgs();
		bigEndian = currentProgram.getLanguage().isBigEndian();
		String proc = currentProgram.getLanguageID().getIdAsString().split(":")[0].toLowerCase();
		List<Case> cases = load(args[0]);
		PrintStream out = new PrintStream(args[1]);
		int pass = 0, fail = 0;
		for (Case c : cases) {
			if (!(" " + c.langs).contains(" " + proc + " ")) {
				continue;
			}
			String err;
			try {
				err = runCase(c);
			}
			catch (Exception e) {
				err = "exception: " + e.getMessage();
			}
			if (err == null) {
				pass++;
				out.println("PASS " + c.name);
			}
			else {
				fail++;
				out.println("FAIL " + c.name + ": " + err);
			}
		}
		out.printf("emulation (%s): %d passed, %d failed%n", currentProgram.getLanguageID(), pass,
			fail);
		out.close();
	}
}
